    --bg-color: #020617;
    --card-bg: #1e293b;
    --text-primary: #f8fafc;
    --text-secondary: #94a3b8;
    --accent: #38bdf8;
    --accent-hover: #7dd3fc;
    --container-width: 1200px;
    --transition: all 0.3s ease;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background-color: var(--bg-color);
    color: var(--text-primary);
    line-height: 1.6;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 2rem;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

/* Header */
header {
    background: rgba(2, 6, 23, 0.8);
    backdrop-filter: blur(10px);
    position: sticky;
    top: 0;
    z-index: 100;
    border-bottom: 1px solid #1e293b;
    padding: 1rem 0;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a:hover {
    color: var(--accent);
}

.nav-actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.cart-icon {
    position: relative;
    cursor: pointer;
}

#cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background: var(--accent);
    color: var(--bg-color);
    font-size: 0.7rem;
    font-weight: bold;
    padding: 2px 6px;
    border-radius: 50%;
}

/* Hero Section */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&q=80&w=1600') center/cover no-repeat;
    margin-bottom: 4rem;
}

.hero-content {
    width: 100%;
}

.editorial-card {
    max-width: 600px;
}

.badge {
    background: var(--accent);
    color: var(--bg-color);
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
    font-weight: bold;
    border-radius: 4px;
    text-transform: uppercase;
    display: inline-block;
    margin-bottom: 1rem;
}

h1 {
    font-size: 4rem;
    line-height: 1.1;
    margin-bottom: 1.5rem;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.btn {
    display: inline-block;
    padding: 1rem 2rem;
    border-radius: 4px;
    font-weight: bold;
    cursor: pointer;
    transition: var(--transition);
}

.primary-btn {
    background: var(--accent);
    color: var(--bg-color);
}

.primary-btn:hover {
    background: var(--accent-hover);
    transform: translateY(-2px);
}

/* Sections */
.section {
    padding: 4rem 0;
}

.section-title {
    font-size: 2rem;
    margin-bottom: 2.5rem;
    position: relative;
    display: inline-block;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: -10px;
    left: 0;
    width: 50px;
    height: 3px;
    background: var(--accent);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--card-bg);
    border-radius: 8px;
    overflow: hidden;
    transition: var(--transition);
    border: 1px solid transparent;
}

.product-card:hover {
    transform: translateY(-5px);
    border-color: var(--accent);
}

.product-image {
    height: 300px;
    background: #334155; /* Placeholder */
    transition: var(--transition);
}

.product-card:nth-child(1) .product-image { background: url('https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&q=80&w=600') center/cover; }
.product-card:nth-child(2) .product-image { background: url('https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=600') center/cover; }
.product-card:nth-child(3) .product-image { background: url('https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&q=80&w=600') center/cover; }
.product-card:nth-child(4) .product-image { background: url('https://images.unsplash.com/photo-1572635196237-14b3f281503f?auto=format&fit=crop&q=80&w=600') center/cover; }

.product-info {
    padding: 1.5rem;
}

.product-info h3 {
    margin-bottom: 0.5rem;
    font-size: 1.1rem;
}

.price {
    color: var(--accent);
    font-weight: bold;
    margin-bottom: 1rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.75rem;
    background: transparent;
    border: 1px solid var(--accent);
    color: var(--accent);
    border-radius: 4px;
    cursor: pointer;
    font-weight: 600;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--accent);
    color: var(--bg-color);
}

/* Deals Section */
.deals-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 2rem;
}

.deal-card {
    background: #0f172a;
    padding: 3rem;
    border-radius: 8px;
    border-left: 4px solid var(--accent);
}

.deal-badge {
    color: var(--accent);
    font-size: 0.9rem;
    font-weight: bold;
    margin-bottom: 1rem;
}

.btn-link {
    display: inline-block;
    margin-top: 1.5rem;
    color: var(--accent);
    font-weight: bold;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
}

.btn-link:hover {
    text-decoration: underline;
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 2rem;
    height: 500px;
}

.editorial-item {
    position: relative;
    border-radius: 8px;
    overflow: hidden;
    display: flex;
    align-items: flex-end;
    padding: 3rem;
    background-size: cover;
    background-position: center;
}

.editorial-item.large {
    background-image: linear-gradient(to top, rgba(0,0,0,0.8), transparent), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=1200');
}

.editorial-item.small {
    background-image: linear-gradient(to top, rgba(0,0,0,0.8), transparent), url('https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&q=80&w=800');
}

.editorial-text h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.editorial-text p {
    color: var(--text-secondary);
    max-width: 400px;
}

/* Footer */
footer {
    padding-top: 6rem;
    padding-bottom: 3rem;
    border-top: 1px solid #1e293b;
    margin-top: 4rem;
}

.footer-content {
    display: grid;
    grid-template-columns: 2fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.footer-brand p {
    color: var(--text-secondary);
}

.footer-links ul {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.footer-links a:hover {
    color: var(--accent);
}

.footer-newsletter h4 {
    margin-bottom: 1rem;
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.75rem;
    border-radius: 4px;
    border: 1px solid #334155;
    background: #1e293b;
    color: white;
}

#newsletter-form button {
    padding: 0.75rem 1.5rem;
    background: var(--accent);
    border: none;
    border-radius: 4px;
    font-weight: bold;
    cursor: pointer;
}

.footer-bottom {
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 968px) {
    .deals-grid, .editorial-grid, .footer-content {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        height: auto;
    }

    .editorial-item {
        height: 400px;
    }

    h1 {
        font-size: 3rem;
    }

    .nav-links {
        display: none; /* Mobile menu not implemented in this scope */
    }
}
